// SourceFormTitle returns the page title for the source form.
func SourceFormTitle(editing bool) string {
	if editing {
		return "Edit Data Source"
	}
	return "Add Data Source"
}

// sourceFormAlpineData builds the Alpine.js x-data attribute string
// with Go values safely injected.
func sourceFormAlpineData(data webui.SourceFormData) string {
	return fmt.Sprintf(`{
		name: %q,
		sourceType: %q,
		configURL: %q,
		configAPIKey: '',
		submitted: false,
		dragOver: false,
		fileName: '',
		fileErrorMsg: '',
		nameError() {
			if (!this.name.trim()) return 'Name is required'
			return ''
		},
		typeError() {
			if (!this.sourceType) return 'Source type is required'
			return ''
		},
		urlError() {
			if (this.sourceType === 'website' && !this.configURL.trim()) return 'URL is required for website sources'
			if (this.configURL && !this.configURL.match(/^https?:\/\/.+/)) return 'Enter a valid URL (http:// or https://)'
			return ''
		},
		apiKeyError() {
			if ((this.sourceType === 'crm_hubspot' || this.sourceType === 'crm_salesforce') && !this.configAPIKey.trim()) return 'API key is required for CRM sources'
			return ''
		},
		fileError() {
			if (this.sourceType !== 'file_upload') return ''
			if (!this.fileName) return 'A file is required'
			return this.fileErrorMsg
		},
		handleFileDrop(event) {
			this.dragOver = false
			const f = event.dataTransfer.files[0]
			this.validateFile(f)
		},
		handleFileSelect(event) {
			const f = event.target.files[0]
			this.validateFile(f)
		},
		validateFile(f) {
			this.fileErrorMsg = ''
			this.fileName = ''
			if (!f) return
			const allowed = ['application/pdf', 'text/csv', 'text/plain', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document']
			if (!allowed.includes(f.type)) {
				this.fileErrorMsg = 'Invalid file type. Allowed: PDF, CSV, TXT, DOCX'
				return
			}
			if (f.size > 10 * 1024 * 1024) {
				this.fileErrorMsg = 'File too large. Maximum size is 10MB'
				return
			}
			this.fileName = f.name
		},
		clearFile() {
			this.fileName = ''
			this.fileErrorMsg = ''
			if (this.$refs.fileInput) this.$refs.fileInput.value = ''
		},
		get hasErrors() {
			return this.nameError() !== '' || this.typeError() !== '' || this.urlError() !== '' || this.apiKeyError() !== '' || this.fileError() !== ''
		}
	}`, data.Name, data.SourceType, data.ConfigURL)
}

